def test_detect_conflicts_overlapping() -> None:
    events = [
        {
            "id": "a",
            "summary": "Meeting A",
            "start": "2026-03-30T09:00:00-04:00",
            "end": "2026-03-30T10:00:00-04:00",
            "status": "confirmed",
            "attendees": [
                {"email": "me@x.com", "self": True, "response_status": "accepted"}
            ],
        },
        {
            "id": "b",
            "summary": "Meeting B",
            "start": "2026-03-30T09:30:00-04:00",
            "end": "2026-03-30T10:30:00-04:00",
            "status": "confirmed",
            "attendees": [
                {"email": "me@x.com", "self": True, "response_status": "accepted"}
            ],
        },
    ]
    conflicts = _detect_conflicts(events)
    assert len(conflicts) == 1


