def test_analyze_skips_declined_new_events(state_dir: Path) -> None:
    """New events the user declined should not appear as changes."""
    _write_events(state_dir, [])
    commit_state("empty baseline", repo_path=state_dir)

    _write_events(
        state_dir,
        [
            {
                "id": "accepted-event",
                "summary": "Accepted Meeting",
                "start": "2026-03-30T09:00:00-04:00",
                "end": "2026-03-30T10:00:00-04:00",
                "all_day": False,
                "status": "confirmed",
                "attendees": [
                    {
                        "email": "me@x.com",
                        "self": True,
                        "response_status": "accepted",
                    }
                ],
            },
            {
                "id": "declined-event",
                "summary": "Declined Meeting",
                "start": "2026-03-30T11:00:00-04:00",
                "end": "2026-03-30T12:00:00-04:00",
                "all_day": False,
                "status": "confirmed",
                "attendees": [
                    {
                        "email": "me@x.com",
                        "self": True,
                        "response_status": "declined",
                    }
                ],
            },
        ],
    )

    analysis = analyze_calendar(repo_path=state_dir)
    new_changes = [c for c in analysis.changes if c.change_type == "new"]
    assert len(new_changes) == 1
    assert new_changes[0].event["id"] == "accepted-event"


